// data.js — loads the two JSON files the site is built from.
//
//   config.json  hand-written in site/config.json; the build fills in repo_url.
//   prods.json   generated by scripts/prodcheck.py (build_site) from every prods/*/prod.yaml.
//                It does not exist in site/ in the repo, only in the built site.
//
// If prodcheck.py adds a field to prods.json, document it in the Prod typedef below.

/**
 * @typedef {Object} Config
 * @property {string} [title]      site name
 * @property {string} [tagline]    line under the title
 * @property {string} [repo_url]   repo address, set at build time (never hard-code it)
 */

/**
 * One released prod, as the gallery sees it.
 * @typedef {Object} Prod
 * @property {string} slug          folder name under prods/, e.g. "2026-decrunch"
 * @property {string} title
 * @property {string|null} group
 * @property {string[]} handles     scene names of the makers (handles only, never legal names)
 * @property {string} platform      "web", "dos", ...
 * @property {string} category      "demo", "intro-4k", "music", "gfx", ...
 * @property {number} year
 * @property {string|null} released ISO date
 * @property {string} license       SPDX id
 * @property {string|null} party
 * @property {string[]|null} tags
 * @property {{type: "human"|"ai"|"hybrid", models?: string[], notes?: string}} provenance
 *           what the makers DECLARED. Shown as written, never corrected by the site.
 * @property {string} entry         file to open, relative to the prod folder
 * @property {boolean} runnable     true when it can run in the browser sandbox
 * @property {string|null} download file to download, relative to the prod folder
 * @property {{label: string, url: string}[]} links
 * @property {boolean} has_nfo
 * @property {number} bytes         measured size of the prod folder
 * @property {string[]} drift       differences between declared and observed, found by CI
 */

/** @returns {Promise<Config>} the config, or {} if it can't be read */
export function loadConfig() {
  return fetch("config.json").then((r) => r.json()).catch(() => ({}));
}

/** @returns {Promise<{generated?: string, prods: Prod[]}>} throws if prods.json can't be read */
export async function loadProds() {
  const r = await fetch("prods.json", { cache: "no-cache" });
  if (!r.ok) throw new Error(`prods.json: HTTP ${r.status}`);
  const data = await r.json();
  return { generated: data.generated, prods: data.prods || [] };
}
